create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now(), currency text not null default 'RUB' check (currency='RUB'));
create table public.accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, type text not null check(type in ('card','cash','deposit','property','investment')), balance_kopecks bigint not null default 0, available boolean not null default true, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, limit_kopecks bigint not null default 0 check(limit_kopecks>=0), suggested_percent numeric(5,2) not null default 0, archived boolean not null default false);
create table public.goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, target_kopecks bigint not null check(target_kopecks>0), balance_kopecks bigint not null default 0 check(balance_kopecks>=0), monthly_kopecks bigint, deadline date, primary_goal boolean not null default false, base_percent numeric(5,2));
create table public.operations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, kind text not null check(kind in ('income','expense','transfer','goal_transfer')), status text not null check(status in ('actual','planned','expected')), amount_kopecks bigint not null check(amount_kopecks>0), operation_date date not null, title text not null, account_id uuid references public.accounts(id) on delete set null, to_account_id uuid references public.accounts(id) on delete set null, category_id uuid references public.categories(id) on delete set null, goal_id uuid references public.goals(id) on delete set null, required boolean not null default false, comment text, created_at timestamptz not null default now());
create table public.obligations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, amount_kopecks bigint not null check(amount_kopecks>=0), due_date date not null, category_id uuid references public.categories(id) on delete set null, paid boolean not null default false, kind text not null check(kind in ('bill','loan')));
create table public.loans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, balance_kopecks bigint not null check(balance_kopecks>=0), annual_rate_percent numeric(6,3) not null check(annual_rate_percent>=0), payment_kopecks bigint not null check(payment_kopecks>0), due_day smallint not null check(due_day between 1 and 31), end_date date, account_id uuid references public.accounts(id) on delete set null);
create table public.debts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, direction text not null check(direction in ('i_owe','owed_to_me')), counterparty text not null, balance_kopecks bigint not null check(balance_kopecks>=0), due_date date, status text not null default 'open' check(status in ('open','settled')));
create table public.budgets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, month date not null, expected_income_kopecks bigint not null default 0, unique(user_id,month));
create table public.budget_limits (id uuid primary key default gen_random_uuid(), budget_id uuid not null references public.budgets(id) on delete cascade, category_id uuid not null references public.categories(id) on delete cascade, limit_kopecks bigint not null check(limit_kopecks>=0), unique(budget_id,category_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, body text not null, read boolean not null default false, obligation_id uuid references public.obligations(id) on delete cascade, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.accounts enable row level security; alter table public.categories enable row level security; alter table public.goals enable row level security; alter table public.operations enable row level security; alter table public.obligations enable row level security; alter table public.loans enable row level security; alter table public.debts enable row level security; alter table public.budgets enable row level security; alter table public.budget_limits enable row level security; alter table public.notifications enable row level security;
create policy "own profile" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own accounts" on public.accounts for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own categories" on public.categories for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own goals" on public.goals for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own operations" on public.operations for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own obligations" on public.obligations for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own loans" on public.loans for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own debts" on public.debts for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own budgets" on public.budgets for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own notifications" on public.notifications for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own budget limits" on public.budget_limits for all using (exists(select 1 from public.budgets b where b.id=budget_id and b.user_id=auth.uid())) with check (exists(select 1 from public.budgets b where b.id=budget_id and b.user_id=auth.uid()));
create index operations_user_date_idx on public.operations(user_id,operation_date desc); create index obligations_user_due_idx on public.obligations(user_id,due_date);
